import{_ as t,o as e,c as r,am as o}from"./chunks/framework._FJXuPhs.js";const h=JSON.parse('{"title":"JVM入门_学习02","description":"","frontmatter":{"title":"JVM入门_学习02","excerpt":"针对JVM相关的内容进行面试前的学习，目前时间是20240425，希望你的努力对得起你的未来，加油。","date":"2024-04-25 19:19:59","updated":"2024-04-25 19:19:59"},"headers":[],"relativePath":"基础/多线程并发与JVM原理/JVM入门_基础概念/JVM入门_学习02.md","filePath":"基础/多线程并发与JVM原理/JVM入门_基础概念/JVM入门_学习02.md","lastUpdated":null}'),l={name:"基础/多线程并发与JVM原理/JVM入门_基础概念/JVM入门_学习02.md"};function n(i,a,s,_,p,d){return e(),r("div",null,[...a[0]||(a[0]=[o('<h3 id="序言" tabindex="-1">序言 <a class="header-anchor" href="#序言" aria-label="Permalink to &quot;序言&quot;">​</a></h3><p>本期是 2024年5月1日对于JVM相关内容进行进阶学习的相关扩展，主要会围绕部分的面试题和自己的确不太了解的内容进行阐述和说明。</p><p>预先知识，选自<img src="" alt="面试煎熬成蛋_面试速刷版_第一版#JVM"></p><h3 id="垃圾回收器" tabindex="-1">垃圾回收器 <a class="header-anchor" href="#垃圾回收器" aria-label="Permalink to &quot;垃圾回收器&quot;">​</a></h3><p>前面讲述到垃圾回收器一般是有 <strong>Serial GC</strong>、<strong>Parallel GC</strong>、<strong>CMS (Concurrent Mark Sweep) GC</strong>、<strong>G1 GC</strong> 四种，如果问道其他的垃圾收集器，暂时只能抱歉说不太了解。</p><ul><li><strong>Serial GC</strong>: 单线程执行，适合单核处理器。</li><li><strong>Parallel GC</strong>: 多线程执行，关注吞吐量。</li><li><strong>CMS (Concurrent Mark Sweep) GC</strong>: 关注最短停顿时间。</li><li><strong>G1 GC</strong>: 面向服务端应用，将堆内存分为多个区域，并并行执行垃圾回收。</li></ul><p>OK，在这四种的基础上，然后我们继续往下去了解。</p><p>一般性能调优，指垃圾回收器，会说一下相关命令：</p><p>可达性分析 + 分代收集</p><h3 id="内存溢出" tabindex="-1">内存溢出 <a class="header-anchor" href="#内存溢出" aria-label="Permalink to &quot;内存溢出&quot;">​</a></h3><p>内存溢出的不同原因： <a href="https://www.bilibili.com/video/BV1Rt4y1G7zN" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1Rt4y1G7zN</a></p><h3 id="线上-gc" tabindex="-1">线上 GC <a class="header-anchor" href="#线上-gc" aria-label="Permalink to &quot;线上 GC&quot;">​</a></h3><hr><p>😔 一直没更新？？ -- 20250820 留言</p>',14)])])}const g=t(l,[["render",n]]);export{h as __pageData,g as default};
